"use client";

/**
 * Short demo film with full sound: a prompt types itself and is sent, an
 * agent works through its tools, the screen builds itself, and the name
 * lands. About 15 seconds at 1920 by 1080. Every scene is a Better Design
 * video component and brings its own sound cues; the film shifts them onto
 * its clock, adds a swish on each cut, and plays them over the music bed in
 * one SoundTrack.
 *
 * ShortDemoBreakdown plays the same film inside a SoundBreakdown, which
 * builds the mix up one layer at a time.
 *
 * Written by Better Design. The sound files are CC0.
 */
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import { useMemo } from "react";
import { AbsoluteFill, Easing } from "remotion";
import { PromptCompose, promptComposeCues } from "@/components/bd-video/prompt-compose";
import { SkeletonBuild, skeletonBuildCues } from "@/components/bd-video/skeleton-build";
import { breakdownFrames, SoundBreakdown } from "@/components/bd-video/sound-breakdown";
import { ToolCalls, toolCallsCues } from "@/components/bd-video/tool-calls";
import { WordmarkBuild, wordmarkBuildCues } from "@/components/bd-video/wordmark-build";
import { whipPan } from "@/components/bd-video/transition-whip-pan";
import { shiftCues, type SoundCue, SoundTrack, type VideoTheme, VideoThemeProvider } from "@/lib/bd-video";

/** Every piece of copy the short demo film shows. */
export interface ShortDemoFilmContent {
  /** The request that types itself into the composer. About 40 characters reads in time. */
  prompt: string;
  agentName: string;
  /** Three tool calls, each "tool-name: argument". */
  tools: string[];
  toolAnswer: string;
  /** The product name in the screen that builds itself. */
  appName: string;
  /** The name that lands at the end. */
  name: string;
}

const DEFAULT_CONTENT: ShortDemoFilmContent = {
  prompt: "Build a dashboard in our design system",
  agentName: "Better Design",
  tools: ["find-design-system: your brand", "get-ui-principle: dashboards", "get-review-rules: visual design"],
  toolAnswer: "Your dashboard is built in your design system and passes the review.",
  appName: "Northwind",
  name: "Better Design",
};

/** Frames per scene, in order: prompt, agent, build, name. */
const SCENES = [130, 130, 115, 130] as const;
const CUT = 15;

/** The frame each scene starts on the film's clock: each cut overlaps the scenes either side of it. */
const sceneStarts = (): number[] => SCENES.map((_, i) => SCENES.slice(0, i).reduce((sum, length) => sum + length - CUT, 0));

/** Every cue in the film, on the film's clock: each scene's own, plus a swish peaking halfway through each cut. */
export function shortDemoCues(content: Partial<ShortDemoFilmContent> = {}, fps = 30): SoundCue[] {
  const c = { ...DEFAULT_CONTENT, ...content };
  const starts = sceneStarts();
  return [
    ...shiftCues(promptComposeCues(c.prompt, fps), starts[0]),
    ...shiftCues(toolCallsCues(c.tools.length), starts[1]),
    ...shiftCues(skeletonBuildCues(), starts[2]),
    ...shiftCues(wordmarkBuildCues(c.name), starts[3]),
    ...starts.slice(1).map((start): SoundCue => ({ sfx: "swish", at: start + CUT / 2 })),
  ];
}

export interface ShortDemoFilmProps {
  content?: Partial<ShortDemoFilmContent>;
  theme?: Partial<VideoTheme>;
  /** Play the sound: every cue, and the music when `music` is on. */
  sound?: boolean;
  /** Mount the music bed. A film ships with and without music from the same cues. */
  music?: boolean;
}

const cut = () => <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: CUT, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />;

/** The four scenes cut together, with no sound of their own. */
function ShortDemoScenes({ content, theme }: Pick<ShortDemoFilmProps, "content" | "theme">) {
  const c = { ...DEFAULT_CONTENT, ...content };
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENES[0]}>
        <PromptCompose prompt={c.prompt} placeholder="Ask Better Design" theme={theme} />
      </TransitionSeries.Sequence>
      {cut()}
      <TransitionSeries.Sequence durationInFrames={SCENES[1]}>
        <ToolCalls tools={c.tools} answer={c.toolAnswer} agentName={c.agentName} theme={theme} />
      </TransitionSeries.Sequence>
      {cut()}
      <TransitionSeries.Sequence durationInFrames={SCENES[2]}>
        <SkeletonBuild appName={c.appName} action="Publish" theme={theme} />
      </TransitionSeries.Sequence>
      {cut()}
      <TransitionSeries.Sequence durationInFrames={SCENES[3]}>
        <WordmarkBuild name={c.name} theme={theme} />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
}

/** A short product film built from Better Design video components, with its sound. */
export function ShortDemoFilm({ content, theme, sound = true, music = true }: ShortDemoFilmProps) {
  const cues = useMemo(() => shortDemoCues(content), [content]);
  return (
    <VideoThemeProvider theme={theme}>
      <AbsoluteFill>
        <ShortDemoScenes content={content} theme={theme} />
        {sound ? <SoundTrack cues={cues} music={music} /> : null}
      </AbsoluteFill>
    </VideoThemeProvider>
  );
}

/** The short demo film inside a sound breakdown: four passes, each adding layers, the last with the music. */
export function ShortDemoBreakdown({ content, theme }: Pick<ShortDemoFilmProps, "content" | "theme">) {
  const cues = useMemo(() => shortDemoCues(content), [content]);
  return (
    <VideoThemeProvider theme={theme}>
      <SoundBreakdown cues={cues} filmFrames={SHORT_DEMO_FILM.durationInFrames} theme={theme}>
        <ShortDemoScenes content={content} theme={theme} />
      </SoundBreakdown>
    </VideoThemeProvider>
  );
}

/** Composition settings. The duration is the scenes minus the three 15-frame cuts. */
export const SHORT_DEMO_FILM = { durationInFrames: 460, fps: 30, width: 1920, height: 1080 } as const;

/** Composition settings for the breakdown: four passes of the film. */
export const SHORT_DEMO_BREAKDOWN = { ...SHORT_DEMO_FILM, durationInFrames: breakdownFrames(SHORT_DEMO_FILM.durationInFrames) } as const;
